package com.example.rokidgeminisecretary;import org.json.*;public class WorkspacePolicyTest{static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}public static void main(String[] args)throws Exception{JSONObject original=new JSONObject().put("calendar_name","家族").put("_inbox_token","secret").put("events",new JSONArray().put(new JSONObject().put("title","診察").put("start","2026-10-20").put("end","2026-10-21").put("all_day",true).put("location","病院").put("description","出典")));JSONObject edit=CalendarDraftEdits.publicCandidate(original);edit.getJSONArray("events").getJSONObject(0).put("title","検査");JSONObject next=CalendarDraftEdits.apply(original,edit);check(next.getString("_inbox_token").equals("secret"));check(!edit.has("_inbox_token"));check(next.getJSONArray("events").getJSONObject(0).getString("description").equals("出典"));check(original.getJSONArray("events").getJSONObject(0).getString("title").equals("診察"));JSONObject e=edit.getJSONArray("events").getJSONObject(0);for(String end:new String[]{"2026-10-20","2026-10-19","bad","2028-10-20"}){e.put("end",end);try{CalendarDraftEdits.apply(original,edit);throw new AssertionError("invalid accepted");}catch(RuntimeException expected){n++;}}e.put("all_day",false).put("start","2026-10-20T10:00:00+09:00").put("end","2026-10-20T11:00:00+09:00");check(CalendarDraftEdits.apply(original,edit).getJSONArray("events").length()==1);e.put("start","2026-10-20T10:00:00");try{CalendarDraftEdits.apply(original,edit);throw new AssertionError();}catch(RuntimeException expected){n++;}long now=1000000;check(NavigationHealthPolicy.snapshot(now,now,now,"",false,"A","A","abcde").getString("status").equals("ready"));check(NavigationHealthPolicy.snapshot(now,now,0,"",false,"A","A","abcde").getString("status").equals("location_missing"));check(NavigationHealthPolicy.snapshot(now,now,now-120001,"",false,"A","A","abcde").getString("status").equals("location_stale"));check(NavigationHealthPolicy.snapshot(now,now-600001,now,"",false,"A","A","abcde").getString("status").equals("route_stale"));check(NavigationHealthPolicy.snapshot(now,now,now,"",false,"A","B","abcde").getString("status").equals("destination_mismatch"));System.out.println("PASS "+n+" review/navigation checks");}}